package com.aoo.bcg.wordcard;
import com.aoo.bcg.gamespi.*;import com.aoo.bcg.gamespi.time.*;import java.util.*;
final class YzchzSession implements AuthoritativeGameSession{
 private final long room,owner;private final RulePayload raw;private final YzchzRules.Config cfg;private final Map<Integer,Long>players=new LinkedHashMap<>();private final Set<Integer>ready=new LinkedHashSet<>();private final Map<Integer,Integer>piao=new LinkedHashMap<>(),lockedHuXi=new LinkedHashMap<>(),wangCount=new LinkedHashMap<>(),discardSource=new LinkedHashMap<>();private final Map<Integer,Set<Integer>>passedChi=new LinkedHashMap<>();private final Map<Integer,List<List<Integer>>>publicGroups=new LinkedHashMap<>();private final List<Object>events=new ArrayList<>();private final OperationDeadlineArbiter arbiter=new OperationDeadlineArbiter();private WordCardState game;private Map<String,Object>waitInfo=Map.of("card",-1,"pos",-1,"type",0,"waiting",false);private int xingNum,genXingNum;private long sequence,version;
 YzchzSession(long room,long owner,RulePayload rules){if(room<=0||owner<=0)throw new IllegalArgumentException("invalid YZCHZ room");this.room=room;this.owner=owner;raw=rules==null?RulePayload.empty():rules;cfg=parse(raw.asMap());players.put(0,owner);initSeat(0);}
 public synchronized GameCommandResult execute(GameCommandRequest r){if(r.roomId()!=room||r.sequence()<=sequence)throw new IllegalArgumentException("invalid YZCHZ command order");long id=id(r.authenticatedUserId());String a=String.valueOf(r.body().asMap().getOrDefault("action","state"));boolean changed=true;switch(a){case"state","CYZCHZGetRoomInfo"->{participant(id);changed=false;}case"join","CYZCHZEnterRoom"->join(r.seatId(),id);case"ready","CYZCHZReadyRoom"->{own(r.seatId(),id);waiting();ready.add(r.seatId());}case"piao","CYZCHZPiaoHua"->{own(r.seatId(),id);waiting();int n=num(r.body().asMap().getOrDefault("piao",0));if(n<0||n>cfg.piaoCap())throw new IllegalArgumentException("invalid piao");piao.put(r.seatId(),n);}case"start","CYZCHZStartGame"->start(id);case"operation","CYZCHZOpCard"->operate(r,id);default->throw new IllegalArgumentException("unsupported YZCHZ action");}sequence=r.sequence();if(changed){version++;events.add(Map.of("version",version,"after",snapshot()));}return new GameCommandResult("wordcard.yzchz.response",r.requestId(),viewFor(id));}
 private void join(int seat,long id){waiting();if(seat<0||seat>=cfg.playerCount()||players.putIfAbsent(seat,id)!=null)throw new IllegalStateException("invalid/occupied YZCHZ seat");initSeat(seat);}
 private void start(long id){if(id!=owner)throw new SecurityException("owner only");waiting();if(players.size()!=cfg.playerCount()||!ready.containsAll(players.keySet().stream().filter(x->x!=0).toList()))throw new IllegalStateException("players not ready");List<Integer>d=new ArrayList<>(YzchzRules.deck(cfg.wangCount()));Collections.shuffle(d,new Random(room));Map<Integer,List<Integer>>h=new LinkedHashMap<>();Map<Integer,Integer>x=new LinkedHashMap<>();for(int seat:players.keySet()){int count=seat==0?21:20;List<Integer>hand=new ArrayList<>();for(int i=0;i<count;i++)hand.add(d.removeFirst());h.put(seat,hand);x.put(seat,0);wangCount.put(seat,(int)hand.stream().filter(c->YzchzRules.type(c)>=41).count());}game=new WordCardState(h,d,List.of(),x,0,WordCardPhase.PLAYING,null,null);waitInfo=Map.of("card",-1,"pos",0,"type",1,"waiting",true);}
 private void operate(GameCommandRequest r,long id){own(r.seatId(),id);if(game==null)throw new IllegalStateException("round not started");Map<String,Object>b=map(r.body().asMap().getOrDefault("payload",Map.of()));WordCardOperation op=WordCardOperation.valueOf(String.valueOf(b.getOrDefault("operation","PASS")));List<Integer>cards=b.get("cards")instanceof Collection<?>c?c.stream().map(YzchzSession::num).toList():List.of();Integer exposed=game.exposedCard();if(op==WordCardOperation.CHI&&!YzchzRules.legalChi(game.hands().get(r.seatId()),exposed,passedChi.get(r.seatId())))throw new IllegalStateException("chi prohibited");if(op==WordCardOperation.PASS&&exposed!=null&&YzchzRules.legalChi(game.hands().get(r.seatId()),exposed,Set.of()))passedChi.get(r.seatId()).add(YzchzRules.type(exposed));int xi=game.huXi().get(r.seatId());int locked=lockedHuXi.get(r.seatId());boolean can=YzchzRules.canHu(xi,locked);game=new WordCardCoreEngine<>(new YzchzRuleSet()).apply(game,new WordCardCommand(op,r.seatId(),cards),new YzchzRuleSet.Context(cfg,xi,locked,can,passedChi.get(r.seatId())));if(Set.of(WordCardOperation.CHI,WordCardOperation.PENG,WordCardOperation.WEI,WordCardOperation.PAO,WordCardOperation.TI).contains(op)){publicGroups.get(r.seatId()).add(List.copyOf(cards));lockedHuXi.merge(r.seatId(),YzchzRules.concealed(cards,op==WordCardOperation.PENG).huXi,Integer::sum);}if(op==WordCardOperation.DISCARD&&!cards.isEmpty())discardSource.put(YzchzRules.type(cards.getFirst()),r.seatId());waitInfo=Map.of("card",game.exposedCard()==null?-1:game.exposedCard(),"pos",r.seatId(),"type",op==WordCardOperation.DRAW?1:2,"waiting",game.phase()==WordCardPhase.PLAYING);if(game.phase()==WordCardPhase.FINISHED){xingNum=game.deck().isEmpty()?0:Collections.frequency(game.hands().get(game.winnerSeat()).stream().map(YzchzRules::type).toList(),YzchzRules.type(game.deck().getFirst()));genXingNum=cfg.genXing()?xingNum:0;}}
 private boolean opposite(int a,int b){return players.size()==2&&a!=b;}
 public synchronized Map<String,Object>viewFor(long viewer){Integer mine=seat(viewer);Map<Integer,Object>s=new LinkedHashMap<>();players.forEach((pos,id)->{List<Integer>h=game==null?List.of():game.hands().get(pos);s.put(pos,Map.of("playerId",id,"ready",ready.contains(pos),"piao",piao.get(pos),"cards",Objects.equals(pos,mine)||game!=null&&game.phase()==WordCardPhase.FINISHED?h:Collections.nCopies(h.size(),0),"cardCount",h.size(),"huXi",game==null?0:game.huXi().get(pos),"lockedHuXi",lockedHuXi.get(pos),"publicGroups",publicGroups.get(pos),"wangCount",wangCount.get(pos),"passedChi",passedChi.get(pos)));});Map<String,Object>v=new LinkedHashMap<>();v.put("roomId",room);v.put("gameCode","yzchz");v.put("started",game!=null);v.put("phase",game==null?"WAITING":game.phase().name());v.put("currentSeat",game==null?-1:game.currentSeat());v.put("winnerSeat",game==null||game.winnerSeat()==null?-1:game.winnerSeat());v.put("waitInfo",waitInfo);v.put("xingNum",xingNum);v.put("genXingNum",genXingNum);v.put("discardSource",discardSource);v.put("seats",Map.copyOf(s));v.put("stateVersion",version);return Map.copyOf(v);}
 public synchronized Map<String,Object>authoritativeState(){return snapshot();}public synchronized long stateVersion(){return version;}synchronized List<Object>events(){return List.copyOf(events);}private Map<String,Object>snapshot(){Map<String,Object>s=new LinkedHashMap<>();s.put("schemaVersion",1);s.put("roomId",room);s.put("ownerId",owner);s.put("players",Map.copyOf(players));s.put("ready",List.copyOf(ready));s.put("piao",Map.copyOf(piao));s.put("passedChi",passedChi);s.put("lockedHuXi",lockedHuXi);s.put("publicGroups",publicGroups);s.put("wangCount",wangCount);s.put("discardSource",discardSource);s.put("waitInfo",waitInfo);s.put("xingNum",xingNum);s.put("genXingNum",genXingNum);s.put("rules",raw.asMap());s.put("sequence",sequence);s.put("stateVersion",version);s.put("game",game==null?"WAITING":encode(game));return Map.copyOf(s);}
 static YzchzSession restore(Map<String,Object>s){if(num(s.get("schemaVersion"))!=1)throw new IllegalArgumentException("bad YZCHZ schema");YzchzSession x=new YzchzSession(lng(s.get("roomId")),lng(s.get("ownerId")),RulePayload.copyOf(map(s.get("rules"))));x.players.clear();map(s.get("players")).forEach((k,v)->x.players.put(Integer.parseInt(k),lng(v)));x.ready.addAll(ints(s.get("ready")));x.piao.clear();map(s.get("piao")).forEach((k,v)->x.piao.put(Integer.parseInt(k),num(v)));x.passedChi.clear();map(s.get("passedChi")).forEach((k,v)->x.passedChi.put(Integer.parseInt(k),new LinkedHashSet<>(ints(v))));x.lockedHuXi.clear();map(s.get("lockedHuXi")).forEach((k,v)->x.lockedHuXi.put(Integer.parseInt(k),num(v)));x.wangCount.clear();map(s.get("wangCount")).forEach((k,v)->x.wangCount.put(Integer.parseInt(k),num(v)));x.discardSource.clear();map(s.get("discardSource")).forEach((k,v)->x.discardSource.put(Integer.parseInt(k),num(v)));x.publicGroups.clear();map(s.get("publicGroups")).forEach((k,v)->x.publicGroups.put(Integer.parseInt(k),groups(v)));x.waitInfo=Map.copyOf(map(s.get("waitInfo")));x.xingNum=num(s.get("xingNum"));x.genXingNum=num(s.get("genXingNum"));if(s.get("game")instanceof Map<?,?>)x.game=decode(map(s.get("game")));x.sequence=lng(s.get("sequence"));x.version=lng(s.get("stateVersion"));return x;}
 static StatePayload replay(StatePayload base,List<Object>events){Map<String,Object>s=new LinkedHashMap<>(base.asMap());long v=lng(s.get("stateVersion"));for(Object raw:events){Map<String,Object>e=map(raw);if(lng(e.get("version"))!=++v)throw new IllegalArgumentException("YZCHZ replay gap");s=new LinkedHashMap<>(map(e.get("after")));}return StatePayload.copyOf(s);}
 private static Map<String,Object>encode(WordCardState s){return Map.of("hands",s.hands(),"deck",s.deck(),"discards",s.discards(),"huXi",s.huXi(),"currentSeat",s.currentSeat(),"phase",s.phase().name(),"exposed",s.exposedCard()==null?-1:s.exposedCard(),"winner",s.winnerSeat()==null?-1:s.winnerSeat());}private static WordCardState decode(Map<String,Object>m){Map<Integer,List<Integer>>h=new LinkedHashMap<>();map(m.get("hands")).forEach((k,v)->h.put(Integer.parseInt(k),ints(v)));Map<Integer,Integer>x=new LinkedHashMap<>();map(m.get("huXi")).forEach((k,v)->x.put(Integer.parseInt(k),num(v)));int e=num(m.get("exposed")),w=num(m.get("winner"));return new WordCardState(h,ints(m.get("deck")),ints(m.get("discards")),x,num(m.get("currentSeat")),WordCardPhase.valueOf(String.valueOf(m.get("phase"))),e<0?null:e,w<0?null:w);}
 public OperationDeadline operationDeadline(){return OperationDeadline.none();}public OperationDeadlineArbiter deadlineArbiter(){return arbiter;}public synchronized List<String>invariantViolations(){List<String>v=new ArrayList<>();if(!players.containsValue(owner))v.add("OWNER_NOT_SEATED");if(game!=null){int cards=game.deck().size()+game.discards().size()+game.hands().values().stream().mapToInt(List::size).sum();if(cards>80+cfg.wangCount())v.add("CARD_CONSERVATION");if(game.phase()==WordCardPhase.FINISHED&&!YzchzRules.canHu(game.huXi().get(game.winnerSeat()),lockedHuXi.getOrDefault(game.winnerSeat(),0)))v.add("WINNER_HU_XI_BELOW_15");}return v;}public synchronized SettlementPayload settlement(int round,String pv){if(game==null||game.phase()!=WordCardPhase.FINISHED)throw new IllegalStateException("round not finished");int w=game.winnerSeat();int handHuXi=game.huXi().get(w),locked=lockedHuXi.getOrDefault(w,0);if(!YzchzRules.canHu(handHuXi,locked))throw new IllegalStateException("finished YZCHZ winner has less than 15 hu-xi");long unit=YzchzRules.settlement(handHuXi+locked,xingNum,genXingNum,piao.get(w),cfg.scoreCap(),wangCount.getOrDefault(w,0));Map<Long,Long>d=new LinkedHashMap<>();long gain=0;for(var e:players.entrySet())if(e.getKey()!=w){long loss=unit+piao.get(e.getKey());d.put(e.getValue(),-loss);gain+=loss;}d.put(players.get(w),gain);return new SettlementPayload(room,round,pv,d);}
 private void initSeat(int seat){piao.put(seat,fixedPiao());passedChi.put(seat,new LinkedHashSet<>());lockedHuXi.put(seat,0);wangCount.put(seat,0);publicGroups.put(seat,new ArrayList<>());}private int fixedPiao(){return 0;}private void waiting(){if(game!=null)throw new IllegalStateException("round started");}private void own(int s,long id){if(!Long.valueOf(id).equals(players.get(s)))throw new SecurityException("seat not owned");}private void participant(long id){if(!players.containsValue(id))throw new SecurityException("not participant");}private Integer seat(long id){return players.entrySet().stream().filter(e->e.getValue()==id).map(Map.Entry::getKey).findFirst().orElse(null);}private static YzchzRules.Config parse(Map<String,Object>r){return new YzchzRules.Config(num(r.getOrDefault("playerCount",3)),num(r.getOrDefault("wangCount",0)),num(r.getOrDefault("piaoCap",4)),num(r.getOrDefault("scoreCap",0)),bool(r,"genXing"));}private static boolean bool(Map<String,Object>m,String k){return Boolean.TRUE.equals(m.get(k));}private static int num(Object v){return v instanceof Number n?n.intValue():Integer.parseInt(String.valueOf(v));}private static long lng(Object v){return v instanceof Number n?n.longValue():Long.parseLong(String.valueOf(v));}private static long id(String v){long x=Long.parseLong(v);if(x<=0)throw new IllegalArgumentException("bad player");return x;}private static List<List<Integer>>groups(Object v){return((Collection<?>)v).stream().map(YzchzSession::ints).toList();}private static List<Integer>ints(Object v){return((Collection<?>)v).stream().map(YzchzSession::num).toList();}@SuppressWarnings("unchecked")private static Map<String,Object>map(Object v){Map<String,Object>x=new LinkedHashMap<>();((Map<?,?>)v).forEach((k,n)->x.put(String.valueOf(k),n));return x;}
}
